'use strict';
const GROUPS={chest:['◈','Грудь'],back:['▤','Спина'],shoulders:['◭','Плечи'],biceps:['💪','Бицепс'],triceps:['⋈','Трицепс'],legs:['🦵','Ноги'],glutes:['◒','Ягодицы'],abs:['▦','Пресс']};
const WEEKDAYS=['Понедельник','Вторник','Среда','Четверг','Пятница','Суббота','Воскресенье'];
const DEFAULT_WEEKDAYS=[0,2,4,1,3,5,6];
const KEY='ritm-gym-prototype-v1',uid=()=>crypto.randomUUID();
const ex=(name,group,sets=3,reps=12,weight='')=>({id:uid(),name,group,sets,reps,weight,note:''});
const initial=()=>({version:1,selected:null,done:{},days:[{id:uid(),name:'Грудь + трицепс',groups:['chest','triceps'],exercises:[ex('Жим лёжа','chest',3,10,40),ex('Жим гантелей на наклонной','chest',3,12,12),ex('Сведение рук в кроссовере','chest'),ex('Разгибание рук на блоке','triceps',3,15)]},{id:uid(),name:'Спина + бицепс',groups:['back','biceps'],exercises:[ex('Тяга верхнего блока','back'),ex('Горизонтальная тяга','back'),ex('Сгибание рук с гантелями','biceps')]},{id:uid(),name:'Ноги + плечи',groups:['legs','shoulders','abs'],exercises:[ex('Жим ногами','legs'),ex('Сгибание ног','legs'),ex('Махи гантелями в стороны','shoulders',3,15),ex('Скручивания','abs',3,15)]}]});
let state,storageError=false;try{const raw=localStorage.getItem(KEY);state=raw?JSON.parse(raw):initial();if(state.version!==1||!Array.isArray(state.days)||!state.done)throw Error();}catch{state=initial();storageError=true;}
// Assign weekdays to existing records without replacing exercises or completion IDs.
state.days.forEach((day,i)=>{if(!Number.isInteger(day.weekday)||day.weekday<0||day.weekday>6)day.weekday=DEFAULT_WEEKDAYS[i%7];});
let editing=null,showForm=false,dirty=false;
const app=document.querySelector('#app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const program=()=>location.pathname.replace(/\/$/,'').endsWith('/program'),current=()=>state.days.find(d=>d.id===state.selected)||state.days[0];
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{storageError=true;notify('Не удалось сохранить в браузере.');return false;}}
function notify(message){const n=document.querySelector('#notice');n.textContent=message;n.style.display='block';clearTimeout(notify.timer);notify.timer=setTimeout(()=>n.style.display='none',3500);}
const badge=g=>GROUPS[g]?`<span class="badge">${GROUPS[g][0]} ${GROUPS[g][1]}</span>`:'';
const info=e=>`${e.sets} × ${e.reps}${e.weight!==''?` · ${esc(e.weight)} кг`:''}`;
function selectDay(id){state.selected=id;editing=null;showForm=false;save();render();}
function setDone(ids,completed){const d=current();if(!d||ids.some(id=>!d.exercises.some(e=>e.id===id)))throw Error('Упражнение не найдено');for(const id of ids){if(completed)state.done[id]=true;else delete state.done[id];}save();render();return {completed:d.exercises.filter(e=>state.done[e.id]).length,total:d.exercises.length};}
function navigate(path){history.pushState({},'',path);editing=null;showForm=false;dirty=false;render();window.scrollTo(0,0);}
function render(){const d=current(),p=program(),done=d?d.exercises.filter(e=>state.done[e.id]).length:0;document.title=`${p?'Программа':'Тренировка'} — Ритм`;document.querySelectorAll('nav a').forEach(a=>{a.removeAttribute('aria-current');if(a.getAttribute('href')===(p?'/gym/program':'/gym'))a.setAttribute('aria-current','page');});
app.innerHTML=`<div class="heading"><div><p class="eyebrow">${p?'СОБЕРИ СВОЙ ПЛАН':'ТВОЙ ТЕМП. ТВОЯ ПРОГРАММА.'}</p><h1>${p?'Программа':'Тренировка'}</h1><p>${p?'Дни, группы мышц и упражнения.':'Выбери день и двигайся по списку.'}</p></div>${p?'<button data-action="add-day">＋ День</button>':''}</div>${state.days.length?`<div class="days" aria-label="Дни программы">${[...state.days].sort((a,b)=>a.weekday-b.weekday).map(day=>`<button class="day ${day.id===d.id?'active':''}" data-day="${day.id}" aria-pressed="${day.id===d.id}"><small>${WEEKDAYS[day.weekday]}</small><strong>${esc(day.name)}</strong><span class="icons">${day.groups.map(badge).join('')}</span></button>`).join('')}</div>`:''}
${!d?`<section class="panel empty"><h2>Твоя программа начинается здесь</h2><p>Добавь первый день и упражнения для него.</p><br>${p?'<button data-action="add-day">Создать день</button>':'<a class="button" href="/gym/program">Составить программу</a>'}</section>`:p?programView(d):`<section class="panel"><div class="panel-head"><div><h2>${esc(d.name)}</h2><p>${done===d.exercises.length&&done>0?'<span class="success">Всё выполнено. Отличная работа!</span>':'Отмечай упражнение после всех подходов.'}</p></div><div class="count">${done}<small> / ${d.exercises.length}</small></div></div><div class="progress" role="progressbar" aria-label="Выполнено упражнений" aria-valuemin="0" aria-valuemax="${d.exercises.length||1}" aria-valuenow="${done}"><span style="width:${d.exercises.length?done/d.exercises.length*100:0}%"></span></div>${d.exercises.length?d.exercises.map((e,i)=>`<label class="exercise ${state.done[e.id]?'done':''}"><span class="number">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(e.name)}</h3><p>${info(e)} · ${GROUPS[e.group]?.[0]||''} ${GROUPS[e.group]?.[1]||''}</p>${e.note?`<p class="note">${esc(e.note)}</p>`:''}</div><input type="checkbox" data-done="${e.id}" ${state.done[e.id]?'checked':''} aria-label="${esc(e.name)} выполнено"></label>`).join(''):'<div class="empty"><p>В этом дне пока нет упражнений.</p><br><a class="button" href="/gym/program">Добавить упражнения</a></div>'}</section><div class="footer"><p class="helper">Отметки сохраняются, даже если закрыть страницу.</p><button class="secondary" data-action="reset" ${done?'':'disabled'}>Начать заново</button></div>`}<p class="helper" style="margin-top:28px">${storageError?'⚠ Сохранение недоступно или данные повреждены.':'Данные хранятся только в этом браузере.'}</p>`;dirty=false;}
function programView(d){return `<section class="panel"><div class="panel-head"><div><h2>${esc(d.name)}</h2><p>${d.exercises.length} упр. в этом дне</p></div><button class="secondary" data-action="edit-day">Изменить день</button></div>${d.exercises.length?d.exercises.map((e,i)=>`<div class="edit-row"><div><h3>${esc(e.name)}</h3><p>${badge(e.group)} &nbsp; ${info(e)}</p>${e.note?`<p class="note">${esc(e.note)}</p>`:''}</div><div class="toolbar"><button class="icon-button" data-up="${e.id}" aria-label="Поднять ${esc(e.name)}" ${i===0?'disabled':''}>↑</button><button class="icon-button" data-down="${e.id}" aria-label="Опустить ${esc(e.name)}" ${i===d.exercises.length-1?'disabled':''}>↓</button><button class="secondary" data-edit="${e.id}" aria-label="Изменить ${esc(e.name)}">Изменить</button><button class="icon-button danger" data-remove="${e.id}" aria-label="Удалить ${esc(e.name)}">×</button></div></div>`).join(''):'<div class="empty"><p>Добавь первое упражнение этого дня.</p></div>'}${showForm?exerciseForm(d):'<div style="margin-top:24px"><button data-action="add-exercise">＋ Упражнение</button></div>'}</section><div class="footer"><p class="helper">Пример программы можно изменить под себя.</p><a href="/gym" class="secondary button">К тренировке →</a></div>`;}
function exerciseForm(d){const e=d.exercises.find(e=>e.id===editing);return `<form id="exercise-form" class="editor"><h2>${e?'Изменить упражнение':'Новое упражнение'}</h2><div class="form-grid"><label class="field full">Название<input name="name" required maxlength="100" placeholder="Например, жим лёжа" value="${esc(e?.name||'')}"></label><label class="field full">Группа мышц<select name="group">${Object.entries(GROUPS).map(([key,[icon,name]])=>`<option value="${key}" ${key===(e?.group||d.groups[0])?'selected':''}>${icon} ${name}</option>`).join('')}</select></label><label class="field">Подходы<input name="sets" type="number" min="1" max="50" step="1" required value="${e?.sets||3}"></label><label class="field">Повторения<input name="reps" type="number" min="1" max="1000" step="1" required value="${e?.reps||12}"></label><label class="field full">Вес, кг · необязательно<input name="weight" type="number" min="0" max="2000" step="0.25" placeholder="Без веса" value="${esc(e?.weight??'')}"></label><label class="field full">Заметка · необязательно<textarea name="note" rows="2" maxlength="500" placeholder="Техника, настройки тренажёра…">${esc(e?.note||'')}</textarea></label></div><div class="toolbar"><button type="submit">Сохранить упражнение</button><button type="button" class="secondary" data-action="cancel-exercise">Отмена</button></div></form>`;}
function modal(content){document.querySelector('dialog')?.remove();const dlg=document.createElement('dialog');dlg.innerHTML=content;document.body.append(dlg);dlg.showModal();dlg.addEventListener('close',()=>dlg.remove());return dlg;}
function confirmAction(title,description,button,action){const dlg=modal(`<h2>${esc(title)}</h2><p>${esc(description)}</p><div class="toolbar" style="margin-top:24px"><button id="confirm">${esc(button)}</button><button class="secondary" id="cancel">Отмена</button></div>`);dlg.querySelector('#cancel').onclick=()=>dlg.close();dlg.querySelector('#confirm').onclick=()=>{dlg.close();action();};}
function withDiscard(action){if(dirty)confirmAction('Не сохранять изменения?','Поля упражнения изменены. При переходе эти изменения потеряются.','Не сохранять',()=>{dirty=false;action();});else action();}
function editDay(create){const d=create?null:current();const weekday=d?.weekday??WEEKDAYS.findIndex((_,i)=>!state.days.some(day=>day.weekday===i));const dlg=modal(`<form id="day-form"><h2>${create?'Новый день':'Настройки дня'}</h2><label class="field" style="margin-top:24px">День недели<select name="weekday" required>${WEEKDAYS.map((label,i)=>`<option value="${i}" ${i===Math.max(0,weekday)?'selected':''}>${label}</option>`).join('')}</select></label><label class="field" style="margin-top:16px">Название<input name="name" required maxlength="70" placeholder="Например, спина + бицепс" value="${esc(d?.name||'')}"></label><fieldset><legend>Группы мышц · выбери одну или несколько</legend><div class="group-options">${Object.entries(GROUPS).map(([key,[icon,name]])=>`<label class="group-choice"><input type="checkbox" name="groups" value="${key}" ${d?.groups.includes(key)?'checked':''}>${icon} ${name}</label>`).join('')}</div></fieldset><p id="group-error" role="alert" style="color:#ffb6ad"></p><div class="toolbar"><button type="submit">Сохранить день</button><button class="secondary" type="button" id="close-day">Отмена</button>${d?'<button class="danger" type="button" id="delete-day">Удалить день</button>':''}</div></form>`);dlg.querySelector('#close-day').onclick=()=>dlg.close();dlg.querySelector('#day-form').onsubmit=event=>{event.preventDefault();const form=event.currentTarget,f=new FormData(form),name=f.get('name').trim();if(!name){form.elements.name.setCustomValidity('Введи название дня');form.elements.name.reportValidity();return;}const weekday=Number(f.get('weekday'));if(!Number.isInteger(weekday)||weekday<0||weekday>6)return;const groups=f.getAll('groups');if(!groups.length){dlg.querySelector('#group-error').textContent='Выбери хотя бы одну группу мышц.';return;}if(d){d.name=name;d.groups=groups;d.weekday=weekday;}else{const day={id:uid(),name,groups,weekday,exercises:[]};state.days.push(day);state.selected=day.id;}save();dlg.close();render();notify('День сохранён');};dlg.querySelector('input[name=name]').oninput=e=>e.target.setCustomValidity('');if(d)dlg.querySelector('#delete-day').onclick=()=>{dlg.close();confirmAction('Удалить день?',`«${d.name}» и все его упражнения будут удалены.`,'Удалить',()=>{for(const e of d.exercises)delete state.done[e.id];state.days=state.days.filter(day=>day.id!==d.id);state.selected=state.days[0]?.id||null;save();render();});};}
document.addEventListener('click',event=>{const link=event.target.closest('a');if(link&&link.origin===location.origin&&['/gym','/gym/program'].includes(link.pathname)&&!event.ctrlKey&&!event.metaKey){event.preventDefault();withDiscard(()=>navigate(link.pathname));return;}const b=event.target.closest('button');if(!b||b.disabled)return;const d=current();if(b.dataset.day){withDiscard(()=>selectDay(b.dataset.day));return;}if(b.dataset.edit){withDiscard(()=>{editing=b.dataset.edit;showForm=true;render();document.querySelector('#exercise-form input').focus();});return;}if(b.dataset.remove){withDiscard(()=>confirmAction('Удалить упражнение?',d.exercises.find(e=>e.id===b.dataset.remove).name,'Удалить',()=>{d.exercises=d.exercises.filter(e=>e.id!==b.dataset.remove);delete state.done[b.dataset.remove];save();render();}));return;}if(b.dataset.up||b.dataset.down){withDiscard(()=>{const id=b.dataset.up||b.dataset.down,i=d.exercises.findIndex(e=>e.id===id),target=i+(b.dataset.up?-1:1);if(target>=0&&target<d.exercises.length){[d.exercises[i],d.exercises[target]]=[d.exercises[target],d.exercises[i]];save();render();}});return;}switch(b.dataset.action){case'add-day':withDiscard(()=>editDay(true));break;case'edit-day':withDiscard(()=>editDay(false));break;case'add-exercise':showForm=true;editing=null;render();document.querySelector('#exercise-form input').focus();break;case'cancel-exercise':withDiscard(()=>{editing=null;showForm=false;render();});break;case'reset':confirmAction('Начать тренировку заново?','Сбросятся только отметки выбранного дня. Упражнения останутся.','Сбросить отметки',()=>setDone(d.exercises.map(e=>e.id),false));break;}});
document.addEventListener('change',e=>{if(e.target.dataset.done)setDone([e.target.dataset.done],e.target.checked);});
document.addEventListener('input',e=>{if(e.target.closest('#exercise-form')){dirty=true;e.target.setCustomValidity?.('');}});
document.addEventListener('submit',event=>{if(event.target.id!=='exercise-form')return;event.preventDefault();const form=event.target,f=new FormData(form),name=f.get('name').trim();if(!name){form.elements.name.setCustomValidity('Введи название упражнения');form.elements.name.reportValidity();return;}const d=current(),updated={id:editing||uid(),name,group:f.get('group'),sets:Number(f.get('sets')),reps:Number(f.get('reps')),weight:f.get('weight')===''?'':Number(f.get('weight')),note:f.get('note').trim()};if(editing){const i=d.exercises.findIndex(e=>e.id===editing);d.exercises[i]=updated;}else d.exercises.push(updated);if(!d.groups.includes(updated.group))d.groups.push(updated.group);editing=null;showForm=false;dirty=false;save();render();notify('Упражнение сохранено');});
window.addEventListener('popstate',()=>{dirty=false;editing=null;showForm=false;render();});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
if(!state.selected)state.selected=state.days[0]?.id||null;save();render();
const context=document.modelContext;if(context?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const tools=[{name:'read_training_program',description:'Read the days, exercises and completion state.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>JSON.parse(JSON.stringify(state))},{name:'set_exercises_completed',description:'Set completion for exercises of the selected day and update the tracker.',inputSchema:{type:'object',properties:{exerciseIds:{type:'array',items:{type:'string'},minItems:1},completed:{type:'boolean'}},required:['exerciseIds','completed'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||!Array.isArray(input.exerciseIds)||!input.exerciseIds.length||input.exerciseIds.some(x=>typeof x!=='string')||typeof input.completed!=='boolean')throw Error('Invalid input');if(dirty)throw Error('Save the draft first');return setDone(input.exerciseIds,input.completed);}}];for(const tool of tools){try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}}
